def recover_tree_brute(root):
    nodes = []
    def inorder(node):
        if node is None:
            return
        inorder(node.left)
        nodes.append(node)
        inorder(node.right)
    inorder(root)
    values = [n.val for n in nodes]
    sorted_values = sorted(values)                          # sort a COPY for comparison
    for i in range(len(values)):
        if values[i] != sorted_values[i]:
            nodes[i].val = sorted_values[i]                     # fix each mismatched position directly

