public class Main {
    static TreeNode first, second, prev;

    static void recoverTree(TreeNode root) {
        first = second = prev = null;
        inorder(root);
        int tmp = first.val;
        first.val = second.val;
        second.val = tmp;                                            // swap the values back
    }

    static void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        if (prev != null && prev.val > node.val) {                  // a 'drop' detected
            if (first == null) first = prev;                            // earlier node of the FIRST drop
            second = node;                                                // always updated, catches a LATER drop too
        }
        prev = node;
        inorder(node.right);
    }
}

