TreeNode *first = nullptr, *second = nullptr, *prev = nullptr;

void inorder(TreeNode* node) {
    if (!node) return;
    inorder(node->left);
    if (prev && prev->val > node->val) {                            // a 'drop' detected
        if (!first) first = prev;                                        // earlier node of the FIRST drop
        second = node;                                                     // always updated, catches a LATER drop too
    }
    prev = node;
    inorder(node->right);
}

void recoverTree(TreeNode* root) {
    first = second = prev = nullptr;
    inorder(root);
    swap(first->val, second->val);                                    // swap the values back
}
